import { useState, useRef } from "react";

// ── Datos iniciales ──────────────────────────────────────────────
const INITIAL_PEDIDOS = {
  recibido: [
    { id: "P-001", cliente: "Valentina Torres", destino: "El Prado, Bga", paquete: "Documentos", hora: "08:15", prioridad: "alta" },
    { id: "P-002", cliente: "Camila Ruiz",     destino: "La Victoria, Bga",  paquete: "Ropa",       hora: "09:30", prioridad: "normal" },
    { id: "P-003", cliente: "Sofía Méndez",    destino: "San Francisco, Bga", paquete: "Medicamentos", hora: "10:00", prioridad: "alta" },
  ],
  en_ruta: [
    { id: "P-004", cliente: "Daniela Vargas",  destino: "Cabecera, Bga",     paquete: "Electrónica", hora: "07:45", prioridad: "normal" },
    { id: "P-005", cliente: "Luciana Gómez",   destino: "Provenza, Bga",     paquete: "Documentos",  hora: "08:00", prioridad: "alta" },
  ],
  entregado: [
    { id: "P-006", cliente: "Isabella Peña",   destino: "Chapinero, Bga",    paquete: "Alimentos",   hora: "06:30", prioridad: "normal" },
  ],
};

const COLUMNAS = [
  { id: "recibido",  label: "Recibido",   icon: "📥", color: "#7C3AED", bg: "#EDE9FE" },
  { id: "en_ruta",   label: "En ruta",    icon: "🛺", color: "#D97706", bg: "#FEF3C7" },
  { id: "entregado", label: "Entregado",  icon: "✅", color: "#059669", bg: "#D1FAE5" },
];

// ── Componente principal ─────────────────────────────────────────
export default function App() {
  const [columnas, setColumnas] = useState(INITIAL_PEDIDOS);
  const [dragging, setDragging] = useState(null); // { id, fromCol }
  const [overCol,  setOverCol]  = useState(null);
  const [modal,    setModal]    = useState(null); // pedido seleccionado para ver detalle
  const [nuevoPedido, setNuevoPedido] = useState(false);
  const [form, setForm] = useState({ cliente: "", destino: "", paquete: "", prioridad: "normal" });
  const dragEl = useRef(null);

  // ── Drag handlers ──────────────────────────────────────────────
  const handleDragStart = (e, id, fromCol) => {
    setDragging({ id, fromCol });
    e.dataTransfer.effectAllowed = "move";
    dragEl.current = e.currentTarget;
    setTimeout(() => { if (dragEl.current) dragEl.current.style.opacity = "0.4"; }, 0);
  };

  const handleDragEnd = () => {
    if (dragEl.current) dragEl.current.style.opacity = "1";
    setDragging(null);
    setOverCol(null);
  };

  const handleDrop = (e, toCol) => {
    e.preventDefault();
    if (!dragging || dragging.fromCol === toCol) { setOverCol(null); return; }
    setColumnas(prev => {
      const src = prev[dragging.fromCol];
      const item = src.find(p => p.id === dragging.id);
      if (!item) return prev;
      return {
        ...prev,
        [dragging.fromCol]: src.filter(p => p.id !== dragging.id),
        [toCol]: [...prev[toCol], item],
      };
    });
    setDragging(null);
    setOverCol(null);
  };

  // ── Agregar pedido ─────────────────────────────────────────────
  const handleAgregar = () => {
    if (!form.cliente || !form.destino || !form.paquete) return;
    const id = "P-" + String(Object.values(columnas).flat().length + 1).padStart(3, "0");
    const hora = new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" });
    const nuevo = { id, ...form, hora };
    setColumnas(prev => ({ ...prev, recibido: [nuevo, ...prev.recibido] }));
    setForm({ cliente: "", destino: "", paquete: "", prioridad: "normal" });
    setNuevoPedido(false);
  };

  // ── Totales para el encabezado ─────────────────────────────────
  const total     = Object.values(columnas).flat().length;
  const entregados = columnas.entregado.length;

  return (
    <div style={s.page}>
      {/* ── Header ── */}
      <header style={s.header}>
        <div style={s.brand}>
          <span style={s.logo}>🦅</span>
          <div>
            <h1 style={s.titulo}>Falcon Mensajería</h1>
            <p style={s.subtitulo}>Servicio femenino de confianza · Bucaramanga</p>
          </div>
        </div>
        <div style={s.stats}>
          {COLUMNAS.map(col => (
            <div key={col.id} style={{ ...s.stat, background: col.bg }}>
              <span style={{ fontSize: 20 }}>{col.icon}</span>
              <div>
                <p style={{ ...s.statNum, color: col.color }}>{columnas[col.id].length}</p>
                <p style={s.statLabel}>{col.label}</p>
              </div>
            </div>
          ))}
          <div style={{ ...s.stat, background: "#F1F5F9" }}>
            <span style={{ fontSize: 20 }}>📦</span>
            <div>
              <p style={{ ...s.statNum, color: "#334155" }}>{total}</p>
              <p style={s.statLabel}>Total hoy</p>
            </div>
          </div>
        </div>
      </header>

      {/* ── Barra de acciones ── */}
      <div style={s.toolbar}>
        <p style={s.hint}>
          {entregados === total && total > 0
            ? "🎉 ¡Todos los pedidos entregados!"
            : `Arrastra las tarjetas entre columnas para actualizar el estado del pedido.`}
        </p>
        <button style={s.btnAdd} onClick={() => setNuevoPedido(true)}>
          + Nuevo pedido
        </button>
      </div>

      {/* ── Tablero Kanban ── */}
      <main style={s.board}>
        {COLUMNAS.map(col => (
          <div
            key={col.id}
            style={{
              ...s.col,
              outline: overCol === col.id ? `2px dashed ${col.color}` : "2px solid transparent",
              background: overCol === col.id ? col.bg : "var(--col-bg, #F8FAFC)",
            }}
            onDragOver={e => { e.preventDefault(); setOverCol(col.id); }}
            onDragLeave={() => setOverCol(null)}
            onDrop={e => handleDrop(e, col.id)}
          >
            {/* Cabecera columna */}
            <div style={{ ...s.colHeader, borderBottom: `3px solid ${col.color}` }}>
              <span style={{ fontSize: 18 }}>{col.icon}</span>
              <h2 style={{ ...s.colTitle, color: col.color }}>{col.label}</h2>
              <span style={{ ...s.badge, background: col.bg, color: col.color }}>
                {columnas[col.id].length}
              </span>
            </div>

            {/* Tarjetas */}
            <div style={s.cards}>
              {columnas[col.id].length === 0 && (
                <div style={s.empty}>Sin pedidos</div>
              )}
              {columnas[col.id].map(pedido => (
                <PedidoCard
                  key={pedido.id}
                  pedido={pedido}
                  colColor={col.color}
                  onDragStart={e => handleDragStart(e, pedido.id, col.id)}
                  onDragEnd={handleDragEnd}
                  onClick={() => setModal(pedido)}
                />
              ))}
            </div>
          </div>
        ))}
      </main>

      {/* ── Modal detalle pedido ── */}
      {modal && (
        <Overlay onClose={() => setModal(null)}>
          <div style={s.modalCard}>
            <div style={s.modalHeader}>
              <h3 style={s.modalTitle}>Detalle del pedido</h3>
              <button style={s.btnClose} onClick={() => setModal(null)}>✕</button>
            </div>
            <div style={s.modalGrid}>
              <Field label="ID" value={modal.id} />
              <Field label="Hora" value={modal.hora} />
              <Field label="Cliente" value={modal.cliente} />
              <Field label="Destino" value={modal.destino} />
              <Field label="Paquete" value={modal.paquete} />
              <Field label="Prioridad" value={modal.prioridad === "alta" ? "⚡ Alta" : "🔵 Normal"} />
            </div>
            <p style={{ fontSize: 13, color: "#94A3B8", marginTop: 16 }}>
              Arrastra la tarjeta en el tablero para cambiar el estado del pedido.
            </p>
          </div>
        </Overlay>
      )}

      {/* ── Modal nuevo pedido ── */}
      {nuevoPedido && (
        <Overlay onClose={() => setNuevoPedido(false)}>
          <div style={s.modalCard}>
            <div style={s.modalHeader}>
              <h3 style={s.modalTitle}>Registrar pedido</h3>
              <button style={s.btnClose} onClick={() => setNuevoPedido(false)}>✕</button>
            </div>
            <div style={s.formGrid}>
              <label style={s.label}>Cliente</label>
              <input style={s.input} value={form.cliente} onChange={e => setForm(f => ({ ...f, cliente: e.target.value }))} placeholder="Nombre de la cliente" />
              <label style={s.label}>Destino</label>
              <input style={s.input} value={form.destino} onChange={e => setForm(f => ({ ...f, destino: e.target.value }))} placeholder="Barrio, ciudad" />
              <label style={s.label}>Tipo de paquete</label>
              <input style={s.input} value={form.paquete} onChange={e => setForm(f => ({ ...f, paquete: e.target.value }))} placeholder="Documentos, ropa, alimentos…" />
              <label style={s.label}>Prioridad</label>
              <select style={s.input} value={form.prioridad} onChange={e => setForm(f => ({ ...f, prioridad: e.target.value }))}>
                <option value="normal">Normal</option>
                <option value="alta">Alta</option>
              </select>
            </div>
            <div style={{ display: "flex", gap: 10, marginTop: 20, justifyContent: "flex-end" }}>
              <button style={s.btnCancel} onClick={() => setNuevoPedido(false)}>Cancelar</button>
              <button style={s.btnPrimary} onClick={handleAgregar}>Registrar pedido</button>
            </div>
          </div>
        </Overlay>
      )}
    </div>
  );
}

// ── Sub-componentes ──────────────────────────────────────────────
function PedidoCard({ pedido, colColor, onDragStart, onDragEnd, onClick }) {
  const esAlta = pedido.prioridad === "alta";
  return (
    <div
      draggable
      onDragStart={onDragStart}
      onDragEnd={onDragEnd}
      onClick={onClick}
      style={{ ...s.card, borderLeft: `4px solid ${colColor}` }}
    >
      <div style={s.cardTop}>
        <span style={s.cardId}>{pedido.id}</span>
        {esAlta && <span style={s.chipAlta}>⚡ Alta</span>}
      </div>
      <p style={s.cardCliente}>{pedido.cliente}</p>
      <p style={s.cardDestino}>📍 {pedido.destino}</p>
      <div style={s.cardBottom}>
        <span style={s.cardPaquete}>📦 {pedido.paquete}</span>
        <span style={s.cardHora}>🕐 {pedido.hora}</span>
      </div>
    </div>
  );
}

function Overlay({ children, onClose }) {
  return (
    <div style={s.overlay} onClick={onClose}>
      <div onClick={e => e.stopPropagation()}>{children}</div>
    </div>
  );
}

function Field({ label, value }) {
  return (
    <div>
      <p style={{ fontSize: 11, color: "#94A3B8", marginBottom: 2, textTransform: "uppercase", letterSpacing: 1 }}>{label}</p>
      <p style={{ fontSize: 15, color: "#0F172A", fontWeight: 500 }}>{value}</p>
    </div>
  );
}

