  cardPaquete: { fontSize: 11, color: "#7C3AED", background: "#EDE9FE", padding: "2px 8px", borderRadius: 20 },
  cardHora: { fontSize: 11, color: "#64748B" },
  overlay: {
    position: "fixed", inset: 0, background: "rgba(15,10,40,0.55)",
    display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100, padding: 16,
  },
  modalCard: {
    background: "#fff", borderRadius: 16, padding: "24px 28px",
    width: "100%", maxWidth: 440, boxShadow: "0 20px 60px rgba(0,0,0,0.2)",
  },
  modalHeader: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 },
  modalTitle: { fontSize: 18, fontWeight: 700, color: "#1E0A3C", margin: 0, fontFamily: "'Playfair Display', serif" },
